import{z as A,x as o,o as t,c as N,q as T,j as l,D as E,d as r,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"STUN / TURN","description":"","frontmatter":{"title":"STUN / TURN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stun-turn.md","filePath":"cs/stun-turn.md","lastUpdated":1791063341000}'),i={name:"cs/stun-turn.md"};function p(d,a,U,R,C,D){const s=o("Mermaid");return t(),N("div",null,[a[2]||(a[2]=T('<h1 id="stun-turn" tabindex="-1">STUN / TURN <a class="header-anchor" href="#stun-turn" aria-label="Permalink to &quot;STUN / TURN&quot;">​</a></h1><div class="epigraph"><p>STUN 问「我在 NAT 外看起来是谁」；TURN 在打不通时分配中继传输。ICE 把两者当候选来源，不是替代。</p><footer>—— 据 RFC 8489 STUN；RFC 8656 TURN 整理</footer></div><p><a href="/cs/webrtc-ice">上一课</a>把候选拿去配对连接，<a href="/cs/ftp-passive">FTP 被动</a>里已见过 NAT 的影子，<a href="/cs/napt">NAPT</a>讲过端口改写。本课补两个候选来源的协议本身：STUN 与 TURN。DASH 留给下一课，不在本课写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机只知自己的私网地址，不知道在 NAT 外呈现出哪个公网映射。STUN 的做法：向公网服务器发绑定请求，服务器把见到的源地址端口写回应答，主机据此得到 srflx 候选；这条 NAT 上的洞只保留短时间，要周期刷新。但 STUN 有边界——对称 NAT 对不同目的地分配不同映射，反射地址对另一端无用，两边都对称时打不通。TURN 是保底：向服务器 Allocate 一个中继地址，数据一律经服务器转发，多付带宽与延迟，但只要 UDP 或 TCP 被放行就总能通；中继必须凭证认证，否则沦为开放中继。</p><p><span class="marginnote">srflx 翻成白话是「服务器眼里的你」：你从 NAT 里发出请求，服务器把看到的公网地址端口原样回给你，这个「镜子里的像」就是一个可试连的候选——它只是个答案，不是通道。</span></p><p>STUN 只回答「我看起来是谁」，不建隧道、不转发数据，不是 VPN。</p><p><span class="marginnote">RFC 8489、8656。TURN over TCP/TLS 应对 UDP 被禁的网络。本课不写绕过企业政策的操作指南。</span></p><h3 id="发现映射与保底中继" tabindex="-1">发现映射与保底中继 <a class="header-anchor" href="#发现映射与保底中继" aria-label="Permalink to &quot;发现映射与保底中继&quot;">​</a></h3><p>分工要清楚：STUN 只发现映射，不与对端交互，不保证两端能通；TURN 用带宽与延迟换可达，是最后手段而非默认。未认证的中继会被人拿去开放转发流量。ICE 把 STUN、TURN、主机候选一起收集、配对试连，谁先通用谁。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计时做对照：只部署 STUN 的方案在严格 NAT 与企业防火墙下连不通，加 TURN 才有可达性保证。流程两步：绑定请求得到反射地址，Allocate 请求得到中继地址。与 GRE 对照：TURN 是用户态中继，逐条流转发；GRE 是 IP 层隧道，封装整个包——层次与粒度都不同。</p><p><span class="marginnote">数字实例：1 Mbps 的视频流若走 TURN 中继，服务器要先收再发，实际吃掉 2 Mbps 服务器带宽，一千路并发就是 2 Gbps；ICE 配对成功走直连后，这部分成本归零——这就是连通后要释放 TURN 分配的原因。</span></p>',13)),(t(),l(B,null,{default:E(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUN%5B%22%E7%BB%91%E5%AE%9A%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20MAP%5B%22%E5%8F%8D%E5%B0%84%E5%9C%B0%E5%9D%80%22%5D%0A%20%20FAIL%5B%22%E7%9B%B4%E8%BF%9E%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20TURN%5B%22%E4%B8%AD%E7%BB%A7%E5%88%86%E9%85%8D%22%5D%0A%20%20TURN%20--%3E%20RELAY%5B%22%E7%BB%8F%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%BD%AC%E5%8F%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"DoH 加密的是 DNS 查询，帮不了 NAT 穿越——那是转发面问题，不是名字解析问题。运营上 TURN 集群的位置重要：GeoDNS 把用户引到最近的 TURN，中继段的 RTT 变小；计费上中继吃双向带宽，是最贵的路径，ICE 在直连候选上成功后应释放 TURN 分配省钱。SSH 反向隧道是同一中继思想的手工版。",-1)),a[5]||(a[5]=e("p",null,"安全上必须凭证：未认证的 TURN 是任何人可用的转发器与流量放大器。",-1)),(t(),l(B,null,{default:E(()=>[n(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ICE%5B%22ICE%EF%BC%9A%E6%94%B6%E9%9B%86%E5%80%99%E9%80%89%E5%B9%B6%E9%85%8D%E5%AF%B9%22%5D%20--%3E%20HOST%5B%22%E4%B8%BB%E6%9C%BA%E5%80%99%E9%80%89%EF%BC%9A%E7%A7%81%E7%BD%91%E5%9C%B0%E5%9D%80%22%5D%0A%20%20ICE%20--%3E%20SRFLX%5B%22srflx%20%E5%80%99%E9%80%89%EF%BC%9ASTUN%20%E5%8F%8D%E5%B0%84%E5%9C%B0%E5%9D%80%22%5D%0A%20%20ICE%20--%3E%20RELAY%5B%22relay%20%E5%80%99%E9%80%89%EF%BC%9ATURN%20%E4%B8%AD%E7%BB%A7%E5%9C%B0%E5%9D%80%22%5D%0A%20%20HOST%20--%3E%20TRY%7B%22%E9%85%8D%E5%AF%B9%E8%AF%95%E8%BF%9E%E6%88%90%E5%8A%9F%EF%BC%9F%22%7D%0A%20%20SRFLX%20--%3E%20TRY%0A%20%20TRY%20--%3E%7C%22%E6%98%AF%22%7C%20DIRECT%5B%22%E7%9B%B4%E8%BF%9E%E9%80%9A%EF%BC%9A%E9%87%8A%E6%94%BE%20TURN%20%E5%88%86%E9%85%8D%E7%9C%81%E9%92%B1%22%5D%0A%20%20TRY%20--%3E%7C%22%E5%90%A6%22%7C%20TURN2%5B%22%E8%B5%B0%20TURN%EF%BC%9A%E7%94%A8%E5%B8%A6%E5%AE%BD%E5%BB%B6%E8%BF%9F%E6%8D%A2%E5%8F%AF%E8%BE%BE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=T('<p><span class="marginnote">常见误区：把 STUN 当隧道用。它只回答「我在 NAT 外是谁」，不转发一个字节，也不是 VPN；真正搬运数据的是直连路径或 TURN 中继——以为部署了 STUN 就能穿透严格 NAT，是实测最常见的翻车点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 ICE-TCP 的全部细节。后课默认：STUN 发现映射，TURN 保底中继；只部署 STUN 在严格 NAT 上不够。下一课<a href="/cs/dash-hls">DASH / HLS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STUN 问「我看起来是谁」，发现 NAT 映射。</li><li>TURN 分配中继候选，用带宽换可达。</li><li>ICE 收集全部候选，选最便宜的通路。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8489；RFC 8656。</li></ul>',5))])}const h=A(i,[["render",p]]);export{u as __pageData,h as default};
